const $=(s,r=document)=>r.querySelector(s),panel=$('#panel'),S={page:'explore',mode:'point',waypoints:[],names:[],routes:[],route:null,selected:null,markers:[],nodes:[],layers:[],poiMarkers:[],geocoders:{},weather:null,weatherOn:false,wind:{speed:15,dir:240},windGrid:null,windGridKey:'',windLoading:false,record:null,watch:null,user:null,navState:null,styleIndex:0,pendingActivity:null,activityView:null,activitySort:'date-desc',lastVoiceKey:'',lastRerouteAt:0,wakeLock:null,wakeLockWanted:false,userMarker:null,previewRun:0};
const mobile=()=>innerWidth<=760,toast=t=>{const e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1900)},store={get:(k,d=[])=>{try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}},set:(k,v)=>localStorage.setItem(k,JSON.stringify(v))},gain=a=>a.reduce((g,v,i)=>g+(i&&v>a[i-1]?v-a[i-1]:0),0),fmt=n=>Number(n||0).toFixed(1);
mapboxgl.accessToken=MAPBOX_TOKEN;const map=new mapboxgl.Map({container:'map',style:'mapbox://styles/mapbox/outdoors-v12',center:[-2.5879,51.4545],zoom:11,preserveDrawingBuffer:true});map.addControl(new mapboxgl.NavigationControl(),'top-right');
const NAV=[['explore','⌂'],['journey','↔'],['adventure','◌'],['routes','▤'],['record','●'],['weather','☁'],['profile','●']];$('#nav').insertAdjacentHTML('beforeend',NAV.map(([p,i])=>`<button class="nav" data-p="${p}"><i>${i}</i><small>${p}</small></button>`).join(''));$('#nav').onclick=e=>{const b=e.target.closest('[data-p]');if(b)open(b.dataset.p)};
function open(p){S.page=p;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.p===p));document.body.classList.toggle('panel-open',p!=='explore'||!mobile());document.body.classList.toggle('map-view',p==='explore');document.body.classList.toggle('navigating',!!S.navState&&p==='explore');const guidance=$('#nav-guidance');if(guidance)guidance.hidden=!(S.navState&&p==='explore');render();setTimeout(()=>map.resize(),30)}function head(t,s){return`<div class="head"><div><h1>${t}</h1><p>${s}</p></div><button class="close">×</button></div>`}function bind(){const b=$('.close');if(b)b.onclick=()=>open('explore')}
