function explore(){panel.innerHTML=head('Explore','Choose transport, adventure, or navigate the displayed route')+`<div class="card hero"><h2>Ride somewhere great</h2><p>Point-to-point cycling, scenic loops, known cycle-route preference and live ride recording. Tap any coloured route on the map to select it and navigate.</p><div class="actions"><button class="btn green" id="p">Point-to-point</button><button class="btn light" id="a">Adventure</button></div></div>`;$('#p').onclick=()=>open('journey');$('#a').onclick=()=>open('adventure')}
function journey(){S.mode='point';panel.innerHTML=head('Point-to-point','Routes calculate when Start and Finish are set')+`<div class="card"><div class="field"><label>Start</label><div class="location-row"><div id="g0"></div><button class="loc" id="l0" title="Use current location">◎</button></div></div><div id="waypointFields"></div><div class="actions"><button class="btn light" id="addWaypoint">＋ Add waypoint</button></div><div class="field"><label>Finish</label><div class="location-row"><div id="g1"></div><button class="loc" id="l1" title="Use current location">◎</button></div></div><div class="actions"><button class="btn light" id="more" style="display:${S.routes.length?'block':'none'}">Show more options</button></div></div><div id="cards"></div>`;geo('#g0',0);geo('#g1',Math.max(1,S.waypoints.length-1));$('#l0').onclick=()=>setHere(0);$('#l1').onclick=()=>setHere(Math.max(1,S.waypoints.length-1));$('#addWaypoint').onclick=addPointToPointWaypoint;$('#more').onclick=()=>pointRoutes(true);renderWaypointFields();cards()}
function addPointToPointWaypoint(){if(S.waypoints.length<2)S.waypoints=[S.waypoints[0]||null,S.waypoints[1]||null];S.waypoints.splice(S.waypoints.length-1,0,null);S.names.splice(S.names.length-1,0,'');journey()}
function renderWaypointFields(){const host=$('#waypointFields');if(!host)return;host.innerHTML='';for(let i=1;i<S.waypoints.length-1;i++){const block=document.createElement('div');block.className='field waypoint-field';block.innerHTML=`<label>Waypoint ${i}</label><div class="location-row"><div id="gw${i}"></div><button class="loc remove-waypoint" data-remove-waypoint="${i}" title="Remove waypoint">×</button></div>`;host.appendChild(block);geo(`#gw${i}`,i);if(S.names[i])S.geocoders[`#gw${i}`]?.setInput(S.names[i])}host.querySelectorAll('[data-remove-waypoint]').forEach(b=>b.onclick=()=>{const i=+b.dataset.removeWaypoint;S.waypoints.splice(i,1);S.names.splice(i,1);markers();journey();if(S.waypoints.filter(Boolean).length>=2)pointRoutes(false)})}
function adventure(){S.mode='loop';panel.innerHTML=head('Adventure','Generate loops that favour cycle routes, views, landmarks and food')+`<div class="card"><div class="field"><label>Start and finish</label><div class="location-row"><div id="ga"></div><button class="loc" id="la">◎</button></div></div><div class="field"><label>Distance target</label><input id="distance" type="range" min="10" max="120" value="45"><b id="distanceV">45 km</b></div><div class="field"><label>Preference</label><select id="pref"><option value="mixed">Balanced</option><option value="scenic">Scenic views</option><option value="landmark">Landmarks</option><option value="food">Food stops</option><option value="cycle">Known cycle routes</option></select></div><div class="actions"><button class="btn primary" id="make">Recommend adventures</button><button class="btn light" id="more">Show more options</button></div></div><div id="cards"></div>`;geo('#ga',0,true);$('#la').onclick=()=>setHere(0,true);$('#distance').oninput=e=>$('#distanceV').textContent=e.target.value+' km';$('#make').onclick=()=>adventureRoutes(false);$('#more').onclick=()=>adventureRoutes(true);cards()}
function geo(id,i,loop=false){const host=$(id),g=new MapboxGeocoder({accessToken:MAPBOX_TOKEN,mapboxgl,marker:false,placeholder:loop?'Adventure start location':i?'Finish location':'Start location'});g.addTo(id);S.geocoders[id]=g;host.closest('.field')?.classList.add('geocoder-field');host.addEventListener('focusin',()=>{document.querySelectorAll('.geocoder-field').forEach(f=>f.classList.remove('geocoder-active'));host.closest('.geocoder-field')?.classList.add('geocoder-active')});host.addEventListener('focusout',()=>setTimeout(()=>host.closest('.geocoder-field')?.classList.remove('geocoder-active'),180));g.on('result',e=>{host.closest('.geocoder-field')?.classList.remove('geocoder-active');S.waypoints[i]=e.result.center;S.names[i]=e.result.place_name;if(loop){S.waypoints=[e.result.center,e.result.center];S.names=[e.result.place_name,e.result.place_name]}markers();if(!loop&&S.waypoints[0]&&S.waypoints[1])pointRoutes(false)})}
async function setHere(i,loop=false){const p=await current();if(!p)return;const name=await getRecognisableLocationName(p);S.waypoints[i]=p;S.names[i]=name;if(loop){S.waypoints=[p,p];S.names=[name,name]}S.geocoders[loop?'#ga':i?'#g1':'#g0']?.setInput(name);markers();map.flyTo({center:p,zoom:14});toast(loop?`Adventure starts and finishes at ${name}`:`${i?'Finish':'Start'} set to ${name}`);if(!loop&&S.waypoints[0]&&S.waypoints[1])pointRoutes(false)}
async function getRecognisableLocationName(p){const [lng,lat]=p,token=`access_token=${MAPBOX_TOKEN}`;try{const addressData=await fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/${lng},${lat}.json?types=address&limit=5&${token}`).then(r=>r.json()),addresses=(addressData.features||[]).map(f=>({...f,_distance:turf.distance(p,f.center,{units:'kilometers'})})).sort((a,b)=>a._distance-b._distance),nearest=addresses.find(f=>f._distance<=.25)||addresses[0];if(nearest){const number=nearest.address||'',street=nearest.text||'',place=(nearest.context||[]).find(x=>x.id?.startsWith('place.'))?.text||'';const exact=`${number} ${street}`.trim();if(exact)return place?`${exact}, ${place}`:exact}const fallback=await fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/${lng},${lat}.json?types=neighborhood,locality,place&limit=1&${token}`).then(r=>r.json());return fallback.features?.[0]?.place_name||'Current location'}catch(e){console.warn('Address lookup failed',e);return'Current location'}}
function locationNameScore(f){const text=`${f.text||''} ${f.place_name||''}`.toLowerCase(),type=f.place_type?.[0]||'',d=f._distance||0;let score=0;if(type==='poi')score+=120;if(/station|railway|terminal|airport/.test(text))score+=90;if(/park|castle|museum|university|hospital|centre|center|landmark/.test(text))score+=45;if(type==='address')score+=20;if(type==='neighborhood'||type==='locality')score+=12;score-=d*80;return score}
async function pointRoutes(append){toast('Finding cycle-friendly routes…');const points=S.waypoints.filter(Boolean);if(points.length<2)return toast('Choose Start and Finish');const base=await directions(points,true),extra=[];if(append&&S.route){const c=S.route.geometry.coordinates,m=c[Math.floor(c.length/2)],b=turf.bearing(c[0],c.at(-1));for(const side of[-90,90,-55])extra.push((await directions([c[0],turf.destination(m,5,b+side).geometry.coordinates,c.at(-1)],false))[0])}await accept([...base,...extra.filter(Boolean)],append)}
async function adventureRoutes(append){const start=S.waypoints[0]||await current();if(!start)return;const km=+$('#distance').value,pref=$('#pref').value,out=[];for(let i=0;i<5;i++){const radius=km/(2*Math.PI),ang=i*72+Math.random()*20,a=turf.destination(start,radius,ang).geometry.coordinates,b=turf.destination(start,radius,ang+120).geometry.coordinates,c=turf.destination(start,radius,ang+240).geometry.coordinates,poi=await findPOI(a,pref,i),r=(await directions([start,poi?.center||a,b,c,start],false))[0];if(r){r.poi=poi;r.name=`Adventure ${i+1}`;out.push(r)}}await accept(out,append)}
async function directions(p,alternatives){try{const c=p.map(x=>x.join(',')).join(';'),d=await fetch(`https://api.mapbox.com/directions/v5/mapbox/cycling/${c}?alternatives=${alternatives}&geometries=geojson&overview=full&steps=true&access_token=${MAPBOX_TOKEN}`).then(r=>r.json());return d.routes||[]}catch{return[]}}
async function findPOI(p,pref,i){const qs={mixed:['viewpoint','landmark','cafe'],scenic:['viewpoint','country park','nature reserve'],landmark:['castle','monument','landmark'],food:['cafe','bakery','restaurant'],cycle:['national cycle route','cycle trail','greenway']}[pref],q=qs[i%qs.length];try{const d=await fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/${encodeURIComponent(q)}.json?types=poi&proximity=${p}&limit=5&access_token=${MAPBOX_TOKEN}`).then(r=>r.json()),f=d.features?.[0];return f?{name:f.text,center:f.center}:null}catch{return null}}
async function accept(rs,append){rs=rs.filter(Boolean);await Promise.all(rs.map(enrich));rs.forEach(r=>r.cycleScore=cycleScore(r));rs.sort((a,b)=>b.cycleScore-a.cycleScore);S.routes=append?[...S.routes,...rs]:rs;S.selected=null;S.route=null;drawAll();cards();stars();updateQuickNav()}
async function enrich(r){const p=sample(r.geometry.coordinates,45);try{const d=await fetch(`https://api.open-meteo.com/v1/elevation?latitude=${p.map(x=>x[1])}&longitude=${p.map(x=>x[0])}`).then(r=>r.json());r.elev=d.elevation||[];r.ascent=gain(r.elev)}catch{r.elev=[];r.ascent=0}r.wind=Array.from({length:12},(_,i)=>Math.sin(i*.8)*S.wind.speed)}
function cycleScore(r){let d=0,t=r.distance||1;(r.legs||[]).forEach(l=>(l.steps||[]).forEach(s=>{const text=`${s.name||''} ${s.ref||''}`.toLowerCase();if(/cycle|ncn|greenway|trail|towpath|shared path/.test(text))d+=s.distance||0}));return Math.round(100*d/t)}function sample(c,n){if(c.length<=n)return c;const l=turf.lineString(c),d=turf.length(l);return Array.from({length:n},(_,i)=>turf.along(l,d*i/(n-1)).geometry.coordinates)}
const colors=['#176bdb','#e34f4f','#139b66','#f28b30','#8b5bd6','#00a6a6'];function drawAll(){S.nodes.forEach(m=>m.remove());S.nodes=[];clearLines();S.routes.forEach((r,i)=>line(`r${i}`,r.geometry,colors[i%colors.length],i?5:7));if(S.routes.length){const f={type:'FeatureCollection',features:S.routes.map(r=>({type:'Feature',geometry:r.geometry,properties:{}}))},b=turf.bbox(f);map.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:mobile()?45:{left:560,right:45,top:45,bottom:45}})}}function line(id,g,c,w){map.addSource(id,{type:'geojson',data:{type:'Feature',geometry:g,properties:{routeIndex:id.startsWith('r')?Number(id.slice(1)):S.selected}}});map.addLayer({id,type:'line',source:id,layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':c,'line-width':w,'line-opacity':.9}});S.layers.push(id);if(id.startsWith('r'))bindMapRouteSelection(id,Number(id.slice(1)))}function clearLines(){S.layers.forEach(id=>{if(map.getLayer(id))map.removeLayer(id);if(map.getSource(id))map.removeSource(id)});S.layers=[]}
function bindMapRouteSelection(layerId,index){map.on('mouseenter',layerId,()=>{map.getCanvas().style.cursor='pointer';setRouteHover(layerId,true)});map.on('mouseleave',layerId,()=>{map.getCanvas().style.cursor='';setRouteHover(layerId,false)});map.on('click',layerId,e=>{e.originalEvent?.preventDefault?.();selectRouteFromMap(index)})}
function setRouteHover(layerId,on){if(!map.getLayer(layerId))return;map.setPaintProperty(layerId,'line-width',on?9:(layerId==='r0'?7:5));map.setPaintProperty(layerId,'line-opacity',on?1:.9)}
function selectRouteFromMap(index){if(!Number.isInteger(index)||!S.routes[index])return;select(index);open('explore');toast(`Route ${index+1} selected. Press Navigation and record now to begin.`);const b=$('#quick-nav');if(b&&!b.hidden)b.animate([{transform:'scale(.97)'},{transform:'scale(1.03)'},{transform:'scale(1)'}],{duration:420})}
function cards(){const x=$('#cards');if(!x)return;if(!S.routes.length){x.innerHTML='<div class="empty">Routes will appear here.</div>';return}x.innerHTML=S.routes.map((r,i)=>`<div class="card route ${S.selected===i?'selected':''}" data-i="${i}" style="--route-color:${colors[i%colors.length]};border-left:7px solid ${colors[i%colors.length]}"><div class="row"><b>${i?'Option '+(i+1):'Recommended'}</b><span class="pill">${r.cycleScore}% cycle-route cues</span></div><div class="stats"><div class="stat"><b>${fmt(r.distance/1000)}</b><small>km</small></div><div class="stat"><b>${Math.round(r.duration/60)}</b><small>min</small></div><div class="stat"><b>${Math.round(r.ascent||0)}</b><small>climb m</small></div><div class="stat"><b>${r.poi?'★':'–'}</b><small>highlight</small></div></div>${r.poi?`<p class="pill">★ ${r.poi.name}</p>`:''}<div class="profiles"><div><div class="label">Elevation</div><canvas class="chart" data-e="${i}" width="420" height="120"></canvas></div><div><div class="label">Wind</div><canvas class="chart" data-w="${i}" width="420" height="120"></canvas></div></div></div>`).join('')+`<div class="actions"><button class="btn light" id="all">Show all routes</button><button class="btn green" id="navRoute">Navigate adventure route</button><button class="btn light" id="preview3d">3D route preview</button><button class="btn light" id="streetPreview">Google Maps preview</button></div>`;x.onclick=e=>{const r=e.target.closest('[data-i]');if(r)select(+r.dataset.i)};$('#all').onclick=()=>{S.selected=null;S.route=null;drawAll();cards();updateQuickNav()};$('#navRoute').onclick=()=>{if(!S.route)return toast('Select one route first');startNavigation()};$('#preview3d').onclick=previewRoute3D;$('#streetPreview').onclick=openGoogleMapsPreview;requestAnimationFrame(drawCharts)}
function previewRoute3D(){if(!S.route)return toast('Select one route first');const run=++S.previewRun,coords=sample(S.route.geometry.coordinates,Math.min(100,S.route.geometry.coordinates.length));let i=0;open('explore');const step=()=>{if(run!==S.previewRun||i>=coords.length-1)return;map.easeTo({center:coords[i],bearing:turf.bearing(coords[i],coords[i+1]),pitch:68,zoom:17.2,duration:650,essential:true});i++;setTimeout(step,680)};step()}
function openGoogleMapsPreview(){if(!S.route)return toast('Select one route first');const c=S.route.geometry.coordinates,p=c[Math.min(2,c.length-1)],next=c[Math.min(3,c.length-1)],heading=next?turf.bearing(p,next):0,url=`https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=${p[1]},${p[0]}&heading=${heading}`;window.open(url,'_blank','noopener,noreferrer')}
function select(i){S.selected=i;S.route=S.routes[i];clearLines();line('chosen',S.route.geometry,colors[i%colors.length],8);nodes();cards();updateQuickNav()}function drawCharts(){document.querySelectorAll('[data-e]').forEach(c=>plot(c,S.routes[+c.dataset.e].elev,'#139b66'));document.querySelectorAll('[data-w]').forEach(c=>plot(c,S.routes[+c.dataset.w].wind,'#176bdb'))}function plot(c,a,col){const x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);if(!a.length)return;const lo=Math.min(...a),hi=Math.max(...a);x.strokeStyle=col;x.lineWidth=3;x.beginPath();a.forEach((v,i)=>{const px=5+i*(w-10)/(a.length-1),py=h-6-(v-lo)*(h-12)/(hi-lo||1);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}
function nodes(){S.nodes.forEach(m=>m.remove());S.nodes=[];const steps=S.route?.legs?.flatMap(l=>l.steps)||[];steps.slice(1,-1).forEach((step,stepIndex)=>{const el=document.createElement('div');el.className='turn';el.title='Drag to reshape this route';const marker=new mapboxgl.Marker({element:el,draggable:true}).setLngLat(step.maneuver.location).addTo(map);marker.on('dragend',async()=>{const dragged=marker.getLngLat().toArray();await reshapeSelectedRoute(dragged,step.maneuver.location);});S.nodes.push(marker)})}
async function reshapeSelectedRoute(dragged,original){if(!S.route||S.selected===null)return;const oldRoute=S.route,isLoop=isClosedLoop(oldRoute.geometry.coordinates);toast(isLoop?'Reshaping loop while preserving its circuit…':'Reshaping selected route…');try{let via;if(isLoop)via=buildLoopViaPoints(oldRoute.geometry.coordinates,dragged,original);else via=[oldRoute.geometry.coordinates[0],dragged,oldRoute.geometry.coordinates.at(-1)];const candidates=await directions(via,false),next=candidates[0];if(!next)throw new Error('No reshaped route returned');if(isLoop&&!validLoop(next.geometry.coordinates,oldRoute.geometry.coordinates))throw new Error('The reshaped result collapsed the loop');await enrich(next);next.poi=oldRoute.poi;next.name=oldRoute.name;next.cycleScore=cycleScore(next);S.routes[S.selected]=next;S.route=next;clearLines();line('chosen',next.geometry,colors[S.selected%colors.length],8);nodes();cards();updateQuickNav();toast(isLoop?'Loop reshaped and preserved':'Route reshaped')}catch(error){console.warn('Route reshaping rejected:',error);S.route=oldRoute;clearLines();line('chosen',oldRoute.geometry,colors[S.selected%colors.length],8);nodes();toast('That edit would collapse the loop, so the previous loop was restored')}}
function isClosedLoop(coords){return coords?.length>3&&turf.distance(coords[0],coords.at(-1))<0.08}
function buildLoopViaPoints(coords,dragged,original){const lineString=turf.lineString(coords),length=turf.length(lineString),snap=turf.nearestPointOnLine(lineString,turf.point(original)),fraction=Math.max(0,Math.min(1,(snap.properties.location||0)/(length||1))),anchors=[];for(let i=0;i<8;i++){const f=i/8;if(Math.abs(f-fraction)>.075)anchors.push({f,coord:turf.along(lineString,length*f).geometry.coordinates})}anchors.push({f:fraction,coord:dragged});anchors.sort((a,b)=>a.f-b.f);const start=coords[0],ordered=[start,...anchors.filter(a=>a.f>.02&&a.f<.98).map(a=>a.coord),start];return dedupeViaPoints(ordered)}
function dedupeViaPoints(points){const out=[];for(const p of points){if(!out.length||turf.distance(out.at(-1),p)>.12)out.push(p)}if(turf.distance(out[0],out.at(-1))>.01)out.push(out[0]);return out.slice(0,24)}
function validLoop(next,previous){if(!isClosedLoop(next))return false;const oldLength=turf.length(turf.lineString(previous)),newLength=turf.length(turf.lineString(next));if(newLength<oldLength*.55)return false;const oldArea=loopAreaScore(previous),newArea=loopAreaScore(next);return newArea>=Math.max(.05,oldArea*.22)}
function loopAreaScore(coords){try{const ring=isClosedLoop(coords)?coords:[...coords,coords[0]];return turf.area(turf.polygon([ring]))/1e6}catch{return 0}} 
function stars(){S.poiMarkers.forEach(m=>m.remove());S.poiMarkers=[];S.routes.forEach((r,i)=>{if(!r.poi)return;const e=document.createElement('button');e.className='poi-star';e.textContent='★';S.poiMarkers.push(new mapboxgl.Marker({element:e}).setLngLat(r.poi.center).setPopup(new mapboxgl.Popup().setHTML(`<b>★ ${r.poi.name}</b><br>Considered for option ${i+1}`)).addTo(map))})}
function markers(){S.markers.forEach(m=>m.remove());S.markers=[];S.waypoints.filter(Boolean).forEach(p=>S.markers.push(new mapboxgl.Marker().setLngLat(p).addTo(map)))}
function updateQuickNav(){const box=$('#quick-nav'),one=S.route&&S.selected!==null,isActive=!!S.record;box.hidden=!one&&!isActive;$('#quick-start').hidden=isActive;$('#ride-live').hidden=!isActive;if(one&&!isActive)$('#quick-start').onclick=startNavigation;box.classList.toggle('recording-active',isActive)}
async function startNavigation(){if(!S.route)return;S.previewRun++;map.stop();await requestScreenWakeLock();S.nodes.forEach(m=>m.remove());S.nodes=[];const steps=S.route.legs?.flatMap(l=>l.steps||[])||[];S.navState={steps,index:0,totalDistance:S.route.distance||0,totalDuration:S.route.duration||0,started:Date.now(),offRouteSince:null,recalculating:false,lastSpokenStep:-1,lastSpokenBand:''};startRecord(true);open('explore');$('#nav-guidance').hidden=false;updateNavigationGuidance(S.pos||S.route.geometry.coordinates[0]);toast('Navigation and recording started')}
async function startRecord(nav=false){await requestScreenWakeLock();if(!S.record)S.record={started:Date.now(),movingMs:0,lastTick:Date.now(),distance:0,gain:0,speed:0,avgSpeed:0,last:null,samples:[],nav,paused:false,stationarySince:null};else S.record.nav=S.record.nav||nav;watch();updateQuickNav();if(S.page==='record')record()}
function record(){if(S.activityView!==null){renderActivityDetail(S.activityView);return}const r=S.record,d=S.pendingActivity,activities=sortedActivities();panel.innerHTML=head('Record','Record rides and review activity analysis')+(r?`<div class="stats"><div class="stat"><b id="speed">${displaySpeed(r).toFixed(1)}</b><small>${r.paused?'average':'current'} km/h</small></div><div class="stat"><b id="dist">${r.distance.toFixed(2)}</b><small>km</small></div><div class="stat"><b id="gain">${Math.round(r.gain)}</b><small>gain m</small></div><div class="stat"><b id="elapsed">${formatClock(r.movingMs)}</b><small>moving time</small></div></div><p class="muted">${r.paused?'Auto-paused after 10 seconds without movement.':'Recording movement.'}</p><div class="actions"><button class="btn light" id="stopPanel">Stop recording</button><button class="btn primary" id="endPanel">End navigation</button></div>`:d?pendingEditor(d):`<div class="card"><button class="btn green" id="start">Start recording</button></div>`)+`<div class="activity-toolbar"><h2>Activities</h2><select id="activitySort"><option value="date-desc">Newest first</option><option value="distance-asc">Distance: low to high</option><option value="distance-desc">Distance: high to low</option><option value="gain-asc">Elevation: low to high</option><option value="gain-desc">Elevation: high to low</option><option value="speed-asc">Speed: low to high</option><option value="speed-desc">Speed: high to low</option><option value="effort-asc">Effort: low to high</option><option value="effort-desc">Effort: high to low</option></select></div><div id="activityCards">${activities.length?activities.map(x=>activityCard(x.activity,x.index)).join(''):'<div class="empty">Completed rides will appear here.</div>'}</div>`;if($('#activitySort')){$('#activitySort').value=S.activitySort;$('#activitySort').onchange=e=>{S.activitySort=e.target.value;record()}}if($('#start'))$('#start').onclick=()=>startRecord(false);if($('#stopPanel'))$('#stopPanel').onclick=stopRecording;if($('#endPanel'))$('#endPanel').onclick=endNavigation;if($('#activityPhotos'))$('#activityPhotos').onchange=e=>attachActivityPhotos([...e.target.files]);if($('#saveActivity'))$('#saveActivity').onclick=savePendingActivity;if($('#discardActivity'))$('#discardActivity').onclick=()=>{S.pendingActivity=null;record()};panel.querySelectorAll('[data-remove-pending-photo]').forEach(b=>b.onclick=()=>{S.pendingActivity.photos.splice(+b.dataset.removePendingPhoto,1);record()});panel.querySelectorAll('[data-activity]').forEach(el=>el.onclick=()=>{S.activityView=+el.dataset.activity;record()})}
function pendingEditor(d){d.photos=d.photos||[];return`<div class="card"><h2>Ride complete</h2><p class="muted">Name the activity and add up to six photos.</p><div class="field"><label>Activity name</label><input id="activityName" value="${escapeHtml(d.name)}"></div><div class="field"><label>Photos</label><input id="activityPhotos" type="file" accept="image/*" multiple></div><div class="photo-grid">${d.photos.map((x,i)=>`<div><img src="${x}"><button data-remove-pending-photo="${i}">×</button></div>`).join('')}</div><div class="stats"><div class="stat"><b>${d.distance.toFixed(2)}</b><small>km</small></div><div class="stat"><b>${d.avgSpeed.toFixed(1)}</b><small>avg km/h</small></div><div class="stat"><b>${Math.round(d.gain)}</b><small>gain m</small></div><div class="stat"><b>${Math.round(d.effortScore||0)}</b><small>effort</small></div></div><div class="actions"><button class="btn green" id="saveActivity">Save activity</button><button class="btn light" id="discardActivity">Discard</button></div></div>`}
function sortedActivities(){const a=store.get('activities').map((activity,index)=>({activity,index})),[key,dir]=S.activitySort.split('-'),value=x=>key==='distance'?x.activity.distance:key==='gain'?x.activity.gain:key==='speed'?x.activity.avgSpeed:key==='effort'?x.activity.effortScore:new Date(x.activity.ended||x.activity.started).getTime();return a.sort((x,y)=>(value(x)-value(y))*(dir==='asc'?1:-1))}
function activityCard(a,i){const cover=(a.photos||[])[0]||a.photo;return`<button class="activity-card" data-activity="${i}">${cover?`<img src="${cover}" alt="Activity photo">`:'<div class="activity-map-thumb">⌁</div>'}<div><b>${escapeHtml(a.name||'Cycling activity')}</b><span>${a.distance.toFixed(1)} km · ${a.avgSpeed.toFixed(1)} km/h · ${Math.round(a.gain||0)} m · effort ${Math.round(a.effortScore||0)}</span></div></button>`}
function renderActivityDetail(index){const activities=store.get('activities'),a=activities[index];if(!a){S.activityView=null;record();return}a.photos=a.photos||[a.photo].filter(Boolean);displayActivityRoute(a);panel.innerHTML=head(a.name||'Activity','Route, photos and performance analysis')+`<div class="activity-gallery">${a.photos.length?a.photos.map((p,i)=>`<div><img src="${p}" alt="Activity photo"><button data-delete-photo="${i}">×</button></div>`).join(''):'<div class="empty">No photos yet.</div>'}</div><div class="actions"><label class="btn light file-label">Add photos<input id="addActivityPhotos" type="file" accept="image/*" multiple hidden></label><button class="btn light" id="renameActivity">Rename</button><button class="btn light" id="shareActivity">Share</button><button class="btn primary" id="socialPng">Export social PNG</button></div><div class="stats"><div class="stat"><b>${a.distance.toFixed(2)}</b><small>km</small></div><div class="stat"><b>${a.avgSpeed.toFixed(1)}</b><small>avg km/h</small></div><div class="stat"><b>${Math.round(a.gain||0)}</b><small>gain m</small></div><div class="stat"><b>${formatClock(a.elapsed)}</b><small>moving time</small></div><div class="stat"><b>${Math.round(a.effortScore||0)}</b><small>effort score</small></div><div class="stat"><b>${Math.round(a.avgPower||0)}</b><small>estimated watts</small></div><div class="stat"><b>${(a.avgPower/(profileData().weight||70)).toFixed(2)}</b><small>W/kg</small></div><div class="stat"><b>${Math.round(a.maxSpeed||0)}</b><small>max km/h</small></div></div><p class="metric-note">Power and effort are estimates based on GPS speed, elevation, rider profile and a simplified cycling-resistance model. They are not power-meter or medical measurements.</p><div class="card"><div class="label">Speed profile</div><canvas id="activitySpeed" class="chart detail-chart" width="500" height="160"></canvas><div class="label">Elevation profile</div><canvas id="activityElevation" class="chart detail-chart" width="500" height="160"></canvas><div class="label">Wind profile at ride time</div><canvas id="activityWind" class="chart detail-chart" width="500" height="160"></canvas><div class="label">Estimated power</div><canvas id="activityPower" class="chart detail-chart" width="500" height="160"></canvas></div><button class="btn light" id="backActivities">Back to activities</button>`;requestAnimationFrame(()=>{plot($('#activitySpeed'),(a.samples||[]).map(x=>(x.speed||0)*3.6),'#f28b30');plot($('#activityElevation'),(a.samples||[]).map(x=>x.elevation).filter(Number.isFinite),'#139b66');plot($('#activityWind'),(a.samples||[]).map(x=>x.windSpeed).filter(Number.isFinite),'#176bdb');plot($('#activityPower'),(a.samples||[]).map(x=>x.estimatedPower||0),'#8b5bd6')});$('#backActivities').onclick=()=>{S.activityView=null;record()};$('#addActivityPhotos').onchange=e=>addPhotosToSavedActivity(index,[...e.target.files]);$('#renameActivity').onclick=()=>renameSavedActivity(index);$('#shareActivity').onclick=()=>shareSavedActivity(a);$('#socialPng').onclick=()=>exportActivityPng(a);panel.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=()=>deleteSavedPhoto(index,+b.dataset.deletePhoto))}
function displayActivityRoute(a){const coords=(a.samples||[]).map(x=>x.pos).filter(Boolean);if(coords.length<2)return;clearLines();line('activity-display',{type:'LineString',coordinates:coords},'#f28b30',7);const b=turf.bbox(turf.lineString(coords));map.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:mobile()?45:{left:560,right:45,top:45,bottom:45}})}
async function attachActivityPhotos(files){if(!S.pendingActivity)return;S.pendingActivity.photos=S.pendingActivity.photos||[];const remaining=Math.max(0,6-S.pendingActivity.photos.length);for(const file of files.slice(0,remaining))S.pendingActivity.photos.push(await compressPhoto(file));record()}
async function addPhotosToSavedActivity(index,files){const activities=store.get('activities'),a=activities[index];a.photos=a.photos||[a.photo].filter(Boolean);for(const file of files.slice(0,Math.max(0,6-a.photos.length)))a.photos.push(await compressPhoto(file));delete a.photo;store.set('activities',activities);renderActivityDetail(index)}
function deleteSavedPhoto(index,photoIndex){const activities=store.get('activities'),a=activities[index];a.photos=(a.photos||[]).filter((_,i)=>i!==photoIndex);store.set('activities',activities);renderActivityDetail(index)}
function renameSavedActivity(index){const activities=store.get('activities'),name=prompt('Activity name',activities[index].name||'Cycling activity');if(name?.trim()){activities[index].name=name.trim();store.set('activities',activities);renderActivityDetail(index)}}
function compressPhoto(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const max=1000,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.68))};img.onerror=reject;img.src=url})}
function savePendingActivity(){if(!S.pendingActivity)return;S.pendingActivity.name=$('#activityName').value.trim()||S.pendingActivity.name;const activities=store.get('activities');activities.unshift(S.pendingActivity);store.set('activities',activities);S.pendingActivity=null;toast('Activity saved');record()}
function escapeHtml(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

function profileData(){return{weight:+localStorage.getItem('profileWeight')||70,height:+localStorage.getItem('profileHeight')||175,bikeWeight:+localStorage.getItem('bikeWeight')||10}}
function estimatePower(speedMs,grade=0,headwind=0){const p=profileData(),mass=p.weight+p.bikeWeight,g=9.80665,crr=.006,rho=1.225,heightM=p.height/100,area=Math.max(.28,Math.min(.55,.34+(heightM-1.7)*.12)),cd=.88,air=Math.max(0,speedMs+headwind),rolling=mass*g*crr,climb=mass*g*grade,aero=.5*rho*cd*area*air*air;return Math.max(0,(rolling+climb+aero)*speedMs/.96)}
function activityMetrics(r){const samples=r.samples||[],powers=samples.map(x=>x.estimatedPower||0),avgPower=powers.length?powers.reduce((a,b)=>a+b,0)/powers.length:0,maxSpeed=Math.max(0,...samples.map(x=>(x.speed||0)*3.6)),durationHours=r.movingMs/36e5,effort=Math.round(Math.max(1,avgPower/100)*durationHours*60+(r.gain||0)/20+(r.distance||0)*1.5);return{avgPower,maxSpeed,effortScore:effort}}
function watch(){if(S.watch!==null)return;S.watch=navigator.geolocation.watchPosition(p=>position(p.coords),e=>toast('Location permission required'),{enableHighAccuracy:true,maximumAge:1000,timeout:15000})}
function position(c){const p=[c.longitude,c.latitude],r=S.record;S.pos=p;updateUserLocationMarker(p,c.heading);if(!r)return;const now=Date.now(),rawSpeed=Math.max(0,c.speed||0),moved=r.last?turf.distance(r.last.pos,p):0,isMoving=rawSpeed>.6||moved>.008;if(isMoving){if(r.paused){r.paused=false;r.stationarySince=null;r.lastTick=now}r.movingMs+=Math.max(0,now-r.lastTick);if(r.last&&moved<.25)r.distance+=moved;if(Number.isFinite(c.altitude)&&Number.isFinite(r.last?.elevation)&&c.altitude>r.last.elevation)r.gain+=c.altitude-r.last.elevation;r.speed=rawSpeed;r.avgSpeed=r.movingMs>0?r.distance/(r.movingMs/36e5):0;r.last={pos:p,elevation:c.altitude,time:now};const prevElevation=r.last?.elevation,segmentM=Math.max(1,moved*1000),grade=Number.isFinite(c.altitude)&&Number.isFinite(prevElevation)?Math.max(-.25,Math.min(.25,(c.altitude-prevElevation)/segmentM)):0,windSpeedKmh=S.windAtPoint?.speed??S.wind.speed,estimatedPower=estimatePower(rawSpeed,grade,Math.max(0,windSpeedKmh/3.6*.25));r.samples.push({pos:p,speed:rawSpeed,elevation:c.altitude,time:now,windSpeed:windSpeedKmh,windDir:S.windAtPoint?.dir??S.wind.dir,grade,estimatedPower});r.stationarySince=null}else{if(!r.stationarySince)r.stationarySince=now;if(now-r.stationarySince>=10000)r.paused=true;r.speed=0}r.lastTick=now;if(r.nav){map.easeTo({center:p,zoom:17,pitch:50,bearing:Number.isFinite(c.heading)?c.heading:map.getBearing()});updateNavigationGuidance(p);checkRouteDeviation(p)}updateLiveDashboard();if(S.page==='record')record()}
function updateUserLocationMarker(pos,heading){if(!S.userMarker){const el=document.createElement('div');el.className='user-location-marker';el.innerHTML='<span class="user-location-arrow">▲</span><i></i>';S.userMarker=new mapboxgl.Marker({element:el,rotationAlignment:'map'}).setLngLat(pos).addTo(map)}else S.userMarker.setLngLat(pos);const arrow=S.userMarker.getElement().querySelector('.user-location-arrow');if(arrow&&Number.isFinite(heading))arrow.style.transform=`rotate(${heading}deg)`}
function updateLiveDashboard(){const r=S.record;if(!r)return;$('#live-speed').textContent=displaySpeed(r).toFixed(1);$('#live-speed-label').textContent=r.paused?'average km/h':'current km/h';$('#live-distance').textContent=r.distance.toFixed(2);$('#live-gain').textContent=Math.round(r.gain);$('#live-time').textContent=formatClock(r.movingMs);updateQuickNav()}
function displaySpeed(r){return r.paused?r.avgSpeed:(r.speed*3.6)}function formatClock(ms){const s=Math.floor(ms/1000),h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${m}:${String(sec).padStart(2,'0')}`}
function updateNavigationGuidance(pos){const n=S.navState,r=S.route;if(!n||!r)return;const lineString=turf.lineString(r.geometry.coordinates),snap=turf.nearestPointOnLine(lineString,turf.point(pos),{units:'kilometers'}),travelled=(snap.properties.location||0)*1000,remaining=Math.max(0,(r.distance||0)-travelled);let chosen=n.steps.at(-1),idx=n.steps.length-1;for(let i=n.index;i<n.steps.length;i++){const loc=n.steps[i].maneuver?.location;if(loc&&turf.distance(pos,loc,{units:'meters'})>12){chosen=n.steps[i];idx=i;break}}n.index=idx;const turnDistance=chosen?.maneuver?.location?turf.distance(pos,chosen.maneuver.location,{units:'meters'}):remaining,instruction=chosen?.maneuver?.instruction||chosen?.name||'Continue on route',arrow=turnArrow(chosen?.maneuver);$('#nav-instruction').textContent=instruction;$('#nav-next-distance').textContent=`${formatDistance(turnDistance)} to next turn`;$('#nav-lane').textContent='';$('#nav-lane').style.display='none';$('#nav-arrow').textContent=arrow;$('#nav-remaining').textContent=`${formatDistance(remaining)} remaining`;if(remaining<25){$('#nav-instruction').textContent='You have arrived';$('#nav-next-distance').textContent='';$('#nav-remaining').textContent='';$('#nav-eta').textContent='';speak('You have arrived');setTimeout(()=>{if(S.record)endNavigation()},1200);return}const speed=Math.max(8,S.record?.avgSpeed||((r.distance/1000)/(r.duration/3600))||18),mins=Math.ceil(remaining/1000/speed*60);$('#nav-eta').textContent=mins>=60?`${Math.floor(mins/60)} hr ${mins%60} min left`:`${mins} min left`;voiceGuidance(idx,instruction,turnDistance)}
function voiceGuidance(stepIndex,instruction,distance){let band=distance<=35?'now':distance<=120?'soon':distance<=500?'advance':'';if(!band)return;const key=`${stepIndex}:${band}`;if(key===S.lastVoiceKey)return;S.lastVoiceKey=key;const text=band==='now'?`${instruction} now`:band==='soon'?`In ${formatDistance(distance)}, ${instruction}`:`In ${formatDistance(distance)}, ${instruction}`;speak(text)}
function speak(text){if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=1.02;u.pitch=1;u.lang=navigator.language||'en-GB';window.speechSynthesis.speak(u)}
async function checkRouteDeviation(pos){const n=S.navState,r=S.route;if(!n||n.recalculating||Date.now()-S.lastRerouteAt<20000)return;const snap=turf.nearestPointOnLine(turf.lineString(r.geometry.coordinates),turf.point(pos),{units:'meters'}),off=snap.properties.dist||0;if(off>45){if(!n.offRouteSince)n.offRouteSince=Date.now();if(Date.now()-n.offRouteSince>6000)await recalculateFrom(pos)}else n.offRouteSince=null}
async function recalculateFrom(pos){const n=S.navState;if(!n)return;n.recalculating=true;S.lastRerouteAt=Date.now();speak('You are off route. Recalculating.');toast('Off route. Recalculating…');try{const destination=S.route.geometry.coordinates.at(-1),d=await fetch(`https://api.mapbox.com/directions/v5/mapbox/cycling/${pos.join(',')};${destination.join(',')}?geometries=geojson&overview=full&steps=true&access_token=${MAPBOX_TOKEN}`).then(r=>r.json()),route=d.routes?.[0];if(!route)throw new Error('No reroute');S.route={...route,elev:S.route.elev,ascent:S.route.ascent};S.routes=[S.route];S.selected=0;n.steps=route.legs?.flatMap(l=>l.steps||[])||[];n.index=0;n.totalDistance=route.distance;n.totalDuration=route.duration;n.offRouteSince=null;S.lastVoiceKey='';clearLines();line('chosen',route.geometry,colors[0],8);speak('New route ready. Continue to the highlighted route.');updateNavigationGuidance(pos)}catch(e){console.error(e);toast('Could not recalculate route')}finally{n.recalculating=false}} 
function laneText(step){const lanes=step?.intersections?.flatMap(i=>i.lanes||[]).filter(l=>l.valid||l.active);if(lanes?.length)return`Use ${lanes.map(l=>(l.indications||[]).join('/')).filter(Boolean).join(', ')} lane`;const road=step?.name||step?.ref;return road?`Continue toward ${road}`:''}
function turnArrow(m={}){const mod=m.modifier||'',type=m.type||'';if(type==='roundabout'||type==='rotary')return'↻';if(mod.includes('left'))return mod.includes('slight')?'↖':'←';if(mod.includes('right'))return mod.includes('slight')?'↗':'→';if(mod.includes('uturn'))return'↩';return'↑'}function formatDistance(m){return m>=1000?`${(m/1000).toFixed(m>=10000?0:1)} km`:`${Math.max(10,Math.round(m/10)*10)} m`}
function stopRecording(){finishRecord(true)}function endNavigation(){finishRecord(true)}async function finishRecord(endNav=true){const r=S.record;if(!r)return;if(S.watch!==null)navigator.geolocation.clearWatch(S.watch);S.watch=null;const startPos=r.samples?.[0]?.pos,endPos=r.samples?.at(-1)?.pos;let defaultName=S.names.length?`${S.names[0]} to ${S.names.at(-1)}`:'Cycling activity';if((!S.names.length||defaultName==='Cycling activity')&&startPos&&endPos){try{const names=await Promise.all([startPos,endPos].map(p=>fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/${p.join(',')}.json?limit=1&access_token=${MAPBOX_TOKEN}`).then(x=>x.json()).then(d=>d.features?.[0]?.text||'Start')));defaultName=`${names[0]} to ${names[1]}`}catch{}}const metrics=activityMetrics(r);S.pendingActivity={...r,...metrics,id:crypto.randomUUID(),name:defaultName,ended:Date.now(),elapsed:r.movingMs,avgSpeed:r.movingMs>0?r.distance/(r.movingMs/36e5):0,photos:[]};S.record=null;await releaseScreenWakeLock();S.navState=null;S.lastVoiceKey='';const guidance=$('#nav-guidance');guidance.hidden=true;$('#nav-lane').textContent='';$('#nav-instruction').textContent='';$('#nav-next-distance').textContent='';$('#nav-remaining').textContent='';$('#nav-eta').textContent='';document.body.classList.remove('navigating');window.speechSynthesis?.cancel();updateQuickNav();S.page='record';document.body.classList.add('panel-open');render();toast('Ride complete. Name it and add a photo.')}
async function shareSavedActivity(a){const text=`${a.name}: ${a.distance.toFixed(1)} km, ${Math.round(a.gain||0)} m climbing, ${a.avgSpeed.toFixed(1)} km/h, effort ${Math.round(a.effortScore||0)}.`;try{const blob=await activityPngBlob(a),file=new File([blob],`${safeName(a.name)}.png`,{type:'image/png'}),data={title:a.name,text,files:[file]};if(navigator.canShare?.({files:[file]}))await navigator.share(data);else if(navigator.share)await navigator.share({title:a.name,text});else{await navigator.clipboard.writeText(text);toast('Activity summary copied')}}catch(e){if(e.name!=='AbortError'){console.error(e);toast('Could not share activity')}}}
async function exportActivityPng(a){const blob=await activityPngBlob(a),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${safeName(a.name)}.png`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function activityPngBlob(a){const c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,1080,1350);g.addColorStop(0,'#15324d');g.addColorStop(1,'#176bdb');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.fillStyle='#fff';x.font='700 48px system-ui';x.fillText('HANDRY OUTLOOK',60,78);x.font='800 58px system-ui';wrapCanvasText(x,a.name||'Cycling activity',60,160,950,68);x.font='800 82px system-ui';x.fillText(`${a.distance.toFixed(1)} KM`,60,300);x.font='32px system-ui';x.fillText(`${a.avgSpeed.toFixed(1)} km/h avg   ·   ${Math.round(a.gain||0)} m climbing`,60,350);x.fillText(`${Math.round(a.avgPower||0)} W estimated   ·   effort ${Math.round(a.effortScore||0)}`,60,395);try{x.drawImage(map.getCanvas(),60,445,960,570)}catch{}const photo=(a.photos||[])[0];if(photo){try{const img=await loadImage(photo);x.drawImage(img,60,1040,300,230)}catch{}}x.fillStyle='#fff';x.font='26px system-ui';x.fillText('Ride planned and recorded with Handry Outlook',60,1320);return new Promise(resolve=>c.toBlob(resolve,'image/png',.92))}
function loadImage(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src})}function safeName(n='activity'){return n.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'activity'}function wrapCanvasText(ctx,text,x,y,maxWidth,lineHeight){const words=text.split(' ');let line='';for(const word of words){const test=line+word+' ';if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line,x,y);line=word+' ';y+=lineHeight}else line=test}ctx.fillText(line,x,y)}
function routes(){const a=store.get('routes');panel.innerHTML=head('Routes','Saved routes')+`<div class="card">${a.length?a.map(x=>`<div class="item"><div><b>${x.name}</b><div class="muted">${fmt(x.route.distance/1000)} km · ${Math.round(x.route.ascent||0)} m climb</div></div></div>`).join(''):'No saved routes'}</div>`}
async function weather(){if(!S.weather)await loadWeather();const w=S.weather;panel.innerHTML=head('Weather','Current and hourly weather')+(w?`<div class="card"><h2>${icon(w.current.weather_code)} ${Math.round(w.current.temperature_2m)}°C</h2><p>Wind ${Math.round(w.current.wind_speed_10m)} km/h · gust ${Math.round(w.current.wind_gusts_10m)} km/h</p></div><div class="card hourly">${w.hourly.time.slice(0,12).map((t,i)=>`<div class="hour"><small>${new Date(t).toLocaleTimeString([],{hour:'2-digit'})}</small><div>${icon(w.hourly.weather_code[i])}</div><b>${Math.round(w.hourly.temperature_2m[i])}°</b></div>`).join('')}</div><button class="btn primary" id="toggleWind">${S.weatherOn?'Hide':'Show'} radar + wind</button>`:'Loading…');if($('#toggleWind'))$('#toggleWind').onclick=toggleWeather}
async function loadWeather(){const p=map.getCenter();S.weather=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${p.lat}&longitude=${p.lng}&current=temperature_2m,weather_code,wind_speed_10m,wind_direction_10m,wind_gusts_10m&hourly=temperature_2m,weather_code&timezone=auto`).then(r=>r.json());S.wind={speed:S.weather.current.wind_speed_10m,dir:S.weather.current.wind_direction_10m};await refreshWindGrid(true)}function icon(c){return c===0?'☀️':c<4?'⛅':c<70?'🌧️':c<80?'🌨️':'⛈️'}
async function toggleWeather(){S.weatherOn=!S.weatherOn;$('#weather').classList.toggle('active',S.weatherOn);if(S.weatherOn){if(!S.weather)await loadWeather();else await refreshWindGrid(true);await radar();windStart()}else{if(map.getLayer('radar'))map.removeLayer('radar');if(map.getSource('radar'))map.removeSource('radar');windStop()}if(S.page==='weather')weather()}
async function radar(){try{const d=await fetch('https://api.rainviewer.com/public/weather-maps.json').then(r=>r.json()),f=d.radar.past.at(-1);if(map.getLayer('radar'))map.removeLayer('radar');if(map.getSource('radar'))map.removeSource('radar');map.addSource('radar',{type:'raster',tiles:[`${d.host}${f.path}/512/{z}/{x}/{y}/2/1_1.png`],tileSize:512,maxzoom:7});map.addLayer({id:'radar',type:'raster',source:'radar',paint:{'raster-opacity':.3}})}catch{toast('Radar unavailable')}}
async function refreshWindGrid(force=false){if(S.windLoading)return;const b=map.getBounds(),zoom=map.getZoom(),cols=zoom<5?8:zoom<8?7:6,rows=zoom<5?6:zoom<8?5:4,key=[b.getWest().toFixed(1),b.getSouth().toFixed(1),b.getEast().toFixed(1),b.getNorth().toFixed(1),cols,rows].join('|');if(!force&&key===S.windGridKey)return;S.windLoading=true;try{const lats=[],lons=[];for(let y=0;y<rows;y++){const fy=y/(rows-1);for(let x=0;x<cols;x++){const fx=x/(cols-1);lons.push(wrapLng(b.getWest()+(b.getEast()-b.getWest())*fx));lats.push(b.getNorth()+(b.getSouth()-b.getNorth())*fy)}}const q=new URLSearchParams({latitude:lats.join(','),longitude:lons.join(','),current:'wind_speed_10m,wind_direction_10m'}),data=await fetch(`https://api.open-meteo.com/v1/forecast?${q}`).then(r=>r.json()),items=Array.isArray(data)?data:[data];S.windGrid={cols,rows,bounds:{west:b.getWest(),east:b.getEast(),south:b.getSouth(),north:b.getNorth()},cells:items.map((d,i)=>({speed:d?.current?.wind_speed_10m??S.wind.speed,dir:d?.current?.wind_direction_10m??S.wind.dir,lat:lats[i],lng:lons[i]}))};S.windGridKey=key}catch(e){console.warn('Spatial wind grid unavailable, using centre wind:',e);S.windGrid=null}finally{S.windLoading=false}}
function wrapLng(lng){return((lng+540)%360)-180}
function windAtScreen(x,y,width,height){const g=S.windGrid;if(!g?.cells?.length)return{speed:S.wind.speed,dir:S.wind.dir};const gx=Math.max(0,Math.min(g.cols-1,x/Math.max(1,width)*(g.cols-1))),gy=Math.max(0,Math.min(g.rows-1,y/Math.max(1,height)*(g.rows-1))),x0=Math.floor(gx),y0=Math.floor(gy),x1=Math.min(g.cols-1,x0+1),y1=Math.min(g.rows-1,y0+1),tx=gx-x0,ty=gy-y0,c00=g.cells[y0*g.cols+x0],c10=g.cells[y0*g.cols+x1],c01=g.cells[y1*g.cols+x0],c11=g.cells[y1*g.cols+x1];const vector=c=>{const a=((c.dir+180)%360)*Math.PI/180,s=Math.max(.1,c.speed);return{x:Math.sin(a)*s,y:-Math.cos(a)*s}},a=vector(c00),b=vector(c10),c=vector(c01),d=vector(c11),vx=(a.x*(1-tx)+b.x*tx)*(1-ty)+(c.x*(1-tx)+d.x*tx)*ty,vy=(a.y*(1-tx)+b.y*tx)*(1-ty)+(c.y*(1-tx)+d.y*tx)*ty;return{vx,vy,speed:Math.hypot(vx,vy)}}
let wf=0;function windStart(){const canvas=$('#wind'),ctx=canvas.getContext('2d'),wrap=$('#map-wrap'),d=devicePixelRatio||1;let rect=wrap.getBoundingClientRect();canvas.width=Math.round(rect.width*d);canvas.height=Math.round(rect.height*d);ctx.setTransform(d,0,0,d,0,0);canvas.style.display='block';const particles=Array.from({length:mobile()?180:340},()=>spawnWindParticle(rect));cancelAnimationFrame(wf);const draw=()=>{rect=wrap.getBoundingClientRect();ctx.clearRect(0,0,rect.width,rect.height);ctx.strokeStyle='rgba(70,210,255,.88)';ctx.lineWidth=1.05;for(const p of particles){const field=windAtScreen(p.x,p.y,rect.width,rect.height),mag=Math.max(.2,field.speed),scale=Math.max(.45,Math.min(2.8,mag/8)),vx=field.vx!==undefined?field.vx/mag*scale:Math.sin(((field.dir+180)%360)*Math.PI/180)*scale,vy=field.vy!==undefined?field.vy/mag*scale:-Math.cos(((field.dir+180)%360)*Math.PI/180)*scale,ox=p.x,oy=p.y;p.x+=vx;p.y+=vy;p.age++;ctx.beginPath();ctx.moveTo(ox-vx*5,oy-vy*5);ctx.lineTo(p.x,p.y);ctx.stroke();if(p.x<-25||p.y<-25||p.x>rect.width+25||p.y>rect.height+25||p.age>p.maxAge)Object.assign(p,spawnWindParticle(rect))}wf=requestAnimationFrame(draw)};draw()}
function spawnWindParticle(rect){return{x:Math.random()*rect.width,y:Math.random()*rect.height,age:Math.random()*100,maxAge:90+Math.random()*90}}
function windStop(){cancelAnimationFrame(wf);const c=$('#wind');c.style.display='none';c.getContext('2d').clearRect(0,0,c.width,c.height)}
let windRefreshTimer=0;function scheduleWindRefresh(){if(!S.weatherOn)return;clearTimeout(windRefreshTimer);windRefreshTimer=setTimeout(async()=>{await refreshWindGrid(false);windStart()},450)}
let auth;function isStandalone(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true}
async function initAuth(){try{const[{initializeApp},{getAuth,GoogleAuthProvider,onAuthStateChanged,signInWithPopup,signOut,setPersistence,indexedDBLocalPersistence,browserLocalPersistence,createUserWithEmailAndPassword,signInWithEmailAndPassword,sendPasswordResetEmail}]=await Promise.all([import('https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js'),import('https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js')]);auth=getAuth(initializeApp(firebaseConfig));try{await setPersistence(auth,indexedDBLocalPersistence)}catch{await setPersistence(auth,browserLocalPersistence)}const provider=new GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});S.loginGoogle=async()=>signInWithPopup(auth,provider);S.loginEmail=(email,password)=>signInWithEmailAndPassword(auth,email,password);S.createEmail=(email,password)=>createUserWithEmailAndPassword(auth,email,password);S.resetEmail=email=>sendPasswordResetEmail(auth,email);S.logout=()=>signOut(auth);onAuthStateChanged(auth,u=>{S.user=u;if(S.page==='profile')profile()})}catch(e){console.error('Firebase authentication unavailable',e)}}
function profile(){const standalone=isStandalone();panel.innerHTML=head('Profile','Account and Home Screen-safe sign-in')+(S.user?`<div class="card"><b>${S.user.displayName||S.user.email||'Rider'}</b><p>${S.user.email||''}</p><button class="btn light" id="logout">Log out</button></div><div class="card"><h3>Rider profile</h3><div class="field"><label>Weight (kg)</label><input id="profileWeight" type="number" min="30" max="250" value="${profileData().weight}"></div><div class="field"><label>Height (cm)</label><input id="profileHeight" type="number" min="120" max="230" value="${profileData().height}"></div><div class="field"><label>Bike + equipment weight (kg)</label><input id="bikeWeight" type="number" min="5" max="40" value="${profileData().bikeWeight}"></div><button class="btn primary" id="saveProfile">Save rider profile</button><p class="metric-note">Used only for estimated cycling power. This estimate is not a power-meter reading.</p></div>`:`<div class="card"><h2>Sign in</h2>${standalone?'<p class="muted"><b>Home Screen app detected.</b> Sign in with email/password below, or try Google sign-in. Your login is stored persistently on this device.</p>':''}<div class="field"><label>Email</label><input id="authEmail" type="email" autocomplete="email" placeholder="name@example.com"></div><div class="field"><label>Password</label><input id="authPassword" type="password" autocomplete="current-password" minlength="6" placeholder="At least 6 characters"></div><div class="actions"><button class="btn primary" id="emailLogin">Sign in</button><button class="btn light" id="emailCreate">Create account</button><button class="btn light" id="emailReset">Reset password</button></div></div><div class="card"><h3>Google account</h3><p class="muted">${standalone?'Google sign-in opens in an account popup. If iOS blocks the popup, use email sign-in above.':'Google sign-in opens in a popup and does not use redirect authentication.'}</p><div class="actions"><button class="btn light" id="googleLogin">Continue with Google</button></div></div>`);if($('#logout'))$('#logout').onclick=()=>S.logout?.();if($('#saveProfile'))$('#saveProfile').onclick=()=>{localStorage.setItem('profileWeight',$('#profileWeight').value);localStorage.setItem('profileHeight',$('#profileHeight').value);localStorage.setItem('bikeWeight',$('#bikeWeight').value);toast('Rider profile saved')};if($('#emailLogin'))$('#emailLogin').onclick=()=>emailAction('login');if($('#emailCreate'))$('#emailCreate').onclick=()=>emailAction('create');if($('#emailReset'))$('#emailReset').onclick=()=>emailAction('reset');if($('#googleLogin'))$('#googleLogin').onclick=()=>S.loginGoogle?.().catch(showAuthError)}
async function emailAction(kind){const email=$('#authEmail')?.value.trim(),password=$('#authPassword')?.value||'';if(!email)return toast('Enter your email address');try{if(kind==='reset'){await S.resetEmail(email);toast('Password reset email sent')}else if(password.length<6)toast('Password must contain at least 6 characters');else if(kind==='create'){await S.createEmail(email,password);toast('Account created')}else{await S.loginEmail(email,password);toast('Signed in')}}catch(e){showAuthError(e)}}
function showAuthError(e){console.error(e);const messages={'auth/invalid-credential':'Incorrect email or password.','auth/email-already-in-use':'An account already uses this email.','auth/popup-blocked':'Allow popups for this Home Screen app, or use email sign-in.','auth/popup-closed-by-user':'Google sign-in was cancelled.','auth/unauthorized-domain':'Add this website domain in Firebase Authentication → Settings → Authorized domains.'};toast(messages[e?.code]||e?.message||'Sign-in failed')}
initAuth()
async function requestScreenWakeLock(){S.wakeLockWanted=true;if(!('wakeLock'in navigator)){toast('Keep-screen-awake is unavailable on this browser');return false}if(document.visibilityState!=='visible')return false;if(S.wakeLock&&!S.wakeLock.released)return true;try{S.wakeLock=await navigator.wakeLock.request('screen');S.wakeLock.addEventListener('release',()=>{S.wakeLock=null;if(S.wakeLockWanted&&document.visibilityState==='visible')setTimeout(requestScreenWakeLock,500)});document.body.classList.add('wake-lock-active');return true}catch(e){console.warn('Screen wake lock was not granted:',e);document.body.classList.remove('wake-lock-active');toast('Could not keep the screen awake. Check Low Power Mode and browser permissions.');return false}}
async function releaseScreenWakeLock(){S.wakeLockWanted=false;document.body.classList.remove('wake-lock-active');if(S.wakeLock&&!S.wakeLock.released){try{await S.wakeLock.release()}catch(e){console.warn('Wake lock release failed',e)}}S.wakeLock=null}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&S.wakeLockWanted&&(S.record||S.navState))requestScreenWakeLock()});
async function current(){return new Promise(res=>navigator.geolocation.getCurrentPosition(p=>res([p.coords.longitude,p.coords.latitude]),()=>{toast('Allow location access');res(null)},{enableHighAccuracy:true}))}$('#locate').onclick=async()=>{const p=await current();if(p)map.flyTo({center:p,zoom:14})};$('#weather').onclick=toggleWeather;$('#stop-record').onclick=stopRecording;$('#end-navigation').onclick=endNavigation;$('#map-style').onclick=showMapStyles;function showMapStyles(){document.querySelector('.style-menu')?.remove();const menu=document.createElement('div');menu.className='style-menu';const styles=[['Outdoors','outdoors-v12'],['Streets','streets-v12'],['Satellite','satellite-streets-v12'],['Navigation day','navigation-day-v1'],['Navigation night','navigation-night-v1']];menu.innerHTML=styles.map(([n,id])=>`<button data-style="${id}">${n}</button>`).join('');$('#map-wrap').appendChild(menu);menu.onclick=e=>{const id=e.target.dataset.style;if(!id)return;map.setStyle(`mapbox://styles/mapbox/${id}`);map.once('style.load',()=>{if(S.selected===null&&S.routes.length)drawAll();else if(S.route){clearLines();line('chosen',S.route.geometry,colors[S.selected%colors.length],8)}if(S.weatherOn)radar()});menu.remove()}}map.on('load',()=>open('explore'));map.on('moveend',scheduleWindRefresh);map.on('zoomend',scheduleWindRefresh);addEventListener('resize',()=>{map.resize();if(S.weatherOn){refreshWindGrid(true).then(windStart)}});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(console.error);
